import{_ as l,a0 as d,w as p,s as o,ao as c,I as t,a1 as n,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Dnsmasq 進階技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Dnsmasq 進階技巧 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Dnsmasq 進階技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Dnsmasq 進階技巧 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180208 Advanced Dnsmasq Tips and Tricks","title":"Dnsmasq 進階技巧","tag":"201803","desc":""},"relativePath":"201803/20180208 Advanced Dnsmasq Tips and Tricks.md","filePath":"[post].md"}'),r={name:"201803/20180208 Advanced Dnsmasq Tips and Tricks.md"};function h(g,s,m,k,u,b){const e=d("Link");return p(),o("div",null,[s[16]||(s[16]=c(`<h1 id="dnsmasq-進階技巧" tabindex="-1">Dnsmasq 進階技巧 <a class="header-anchor" href="#dnsmasq-進階技巧" aria-label="Permalink to “Dnsmasq 進階技巧”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_3.25.47_pm.png?itok=2YaDe86d" alt=""></p><p>許多人熟知並熱愛 Dnsmasq，並在他們的本地域名服務上使用它。今天我們將介紹進階配置文件管理、如何測試你的配置、一些基礎的安全知識、DNS 泛域名、快速 DNS 配置，以及其他一些技巧與竅門。下個星期我們將繼續詳細講解如何配置 DNS 和 DHCP。</p><h3 id="測試配置" tabindex="-1">測試配置 <a class="header-anchor" href="#測試配置" aria-label="Permalink to “測試配置”">​</a></h3><p>當你測試新的配置的時候，你應該從命令列運行 Dnsmasq，而不是使用守護進程。下面的例子演示瞭如何不用守護進程運行它，同時顯示指令的輸出並保留運行日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnsmasq --no-daemon --log-queries</span></span>
<span class="line"><span>dnsmasq: started, version 2.75 cachesize 150</span></span>
<span class="line"><span>dnsmasq: compile time options: IPv6 GNU-getopt</span></span>
<span class="line"><span> DBus i18n IDN DHCP DHCPv6 no-Lua TFTP conntrack</span></span>
<span class="line"><span> ipset auth DNSSEC loop-detect inotify</span></span>
<span class="line"><span>dnsmasq: reading /etc/resolv.conf</span></span>
<span class="line"><span>dnsmasq: using nameserver 192.168.0.1#53</span></span>
<span class="line"><span>dnsmasq: read /etc/hosts - 9 addresses</span></span></code></pre></div><p>在這個小例子中你能看到許多有用的信息，包括版本、編譯參數、系統名字服務文件，以及它的監聽地址。可以使用 <code>Ctrl+C</code> 停止進程。在默認情況下，Dnsmasq 沒有自己的日誌文件，所以日誌會被記錄到 <code>/var/log</code> 目錄下的多個地方。你可以使用經典的 <code>grep</code> 來找到 Dnsmasq 的日誌文件。下面這條指令會遞歸式地搜索 <code>/var/log</code>，在每個匹配的文件名之後顯示匹配的行號，並忽略 <code>/var/log/dist-upgrade</code> 裏的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep -ir --exclude-dir=dist-upgrade dnsmasq /var/log/</span></span></code></pre></div><p>使用 <code>grep --exclude-dir=</code> 時有一個有趣的小陷阱需要注意：不要使用完整路徑，而應該只寫目錄名稱。</p><p>你可以使用如下的命令列參數來讓 Dnsmasq 使用你指定的文件作為它專屬的日誌文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnsmasq --no-daemon --log-queries --log-facility=/var/log/dnsmasq.log</span></span></code></pre></div><p>或者在你的 Dnsmasq 配置文件中加上 <code>log-facility=/var/log/dnsmasq.log</code>。</p><h3 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to “配置文件”">​</a></h3><p>Dnsmasq 的配置文件位於 <code>/etc/dnsmasq.conf</code>。你的 Linux 發行版也可能會使用 <code>/etc/default/dnsmasq</code>、<code>/etc/dnsmasq.d/</code>，或者 <code>/etc/dnsmasq.d-available/</code>（不，我們不能統一標準，因為這違反了 <ruby>Linux 七嘴八舌秘密議會<rt>Linux Cat Herd Ruling Cabal</rt></ruby>的旨意）。你有很多自由來隨意安置你的配置文件。</p><p><code>/etc/dnsmasq.conf</code> 是德高望重的老大。Dnsmasq 在啓動時會最先讀取它。<code>/etc/dnsmasq.conf</code> 可以使用 <code>conf-file=</code> 選項來調用其他的配置文件，例如 <code>conf-file=/etc/dnsmasqextrastuff.conf</code>，或使用 <code>conf-dir=</code> 選項來調用目錄下的所有文件，例如 <code>conf-dir=/etc/dnsmasq.d</code>。</p><p>每當你對配置文件進行了修改，你都必須重啓 Dnsmasq。</p><p>你也可以根據擴展名來包含或忽略配置文件。星號表示包含，不加星號表示排除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>conf-dir=/etc/dnsmasq.d/, *.conf, *.foo</span></span>
<span class="line"><span>conf-dir=/etc/dnsmasq.d, .old, .bak, .tmp</span></span></code></pre></div><p>你可以用 <code>--addn-hosts=</code> 選項來把你的主機配置分佈在多個文件中。</p><p>Dnsmasq 包含了一個語法檢查器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnsmasq --test</span></span>
<span class="line"><span>dnsmasq: syntax check OK.</span></span></code></pre></div><h3 id="實用配置" tabindex="-1">實用配置 <a class="header-anchor" href="#實用配置" aria-label="Permalink to “實用配置”">​</a></h3><p>永遠加入這幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>domain-needed</span></span>
<span class="line"><span>bogus-priv</span></span></code></pre></div><p>它們可以避免含有格式出錯的域名或私有 IP 地址的數據包離開你的網絡。</p><p>讓你的名字服務只使用 Dnsmasq，而不去使用 <code>/etc/resolv.conf</code> 或任何其他的名字服務文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>no-resolv</span></span></code></pre></div><p>使用其他的域名服務器。第一個例子是隻對於某一個域名使用不同的域名服務器。第二個和第三個例子是 OpenDNS 公用服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server=/fooxample.com/192.168.0.1</span></span>
<span class="line"><span>server=208.67.222.222</span></span>
<span class="line"><span>server=208.67.220.220</span></span></code></pre></div><p>你也可以將某些域名限制為只能本地解析，但不影響其他域名。這些被限制的域名只能從 <code>/etc/hosts</code> 或 DHCP 解析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local=/mehxample.com/</span></span>
<span class="line"><span>local=/fooxample.com/</span></span></code></pre></div><p>限制 Dnsmasq 監聽的網絡接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>interface=eth0</span></span>
<span class="line"><span>interface=wlan1</span></span></code></pre></div><p>Dnsmasq 在默認設置下會讀取並使用 <code>/etc/hosts</code>。這是一個又快又好的配置大量域名的方法，並且 <code>/etc/hosts</code> 只需要和 Dnsmasq 在同一台電腦上。你還可以讓這個過程再快一些，可以在 <code>/etc/hosts</code> 文件中只寫主機名，然後用 Dnsmasq 來添加域名。<code>/etc/hosts</code> 看上去是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 localhost</span></span>
<span class="line"><span>192.168.0.1 host2</span></span>
<span class="line"><span>192.168.0.2 host3</span></span>
<span class="line"><span>192.168.0.3 host4</span></span></code></pre></div><p>然後把下面這幾行寫入 <code>dnsmasq.conf</code>（當然，要換成你自己的域名）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>expand-hosts</span></span>
<span class="line"><span>domain=mehxample.com</span></span></code></pre></div><p>Dnsmasq 會自動把這些主機名擴展為完整的域名，比如 <code>host2</code> 會變為 <code>host2.mehxample.com</code>。</p><h3 id="dns-泛域名" tabindex="-1">DNS 泛域名 <a class="header-anchor" href="#dns-泛域名" aria-label="Permalink to “DNS 泛域名”">​</a></h3><p>一般來説，使用 DNS 泛域名不是一個好習慣，因為它們太容易被誤用了。但它們有時會很有用，比如在你的局域網的嚴密保護之下的時候。一個例子是使用 DNS 泛域名會讓 Kubernetes 集羣變得容易管理許多，除非你喜歡給你成百上千的應用寫 DNS 記錄。假設你的 Kubernetes 域名是 mehxample.com，那麼下面這行配置可以讓 Dnsmasq 解析所有對 mehxample.com 的請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>address=/mehxample.com/192.168.0.5</span></span></code></pre></div><p>這裏使用的地址是你的集羣的公網 IP 地址。這會響應對 mehxample.com 的所有主機名和子域名的請求，除非請求的目標地址已經在 DHCP 或者 <code>/etc/hosts</code> 中配置過。</p><p>下星期我們將探索更多的管理 DNS 和 DHCP 的細節，包括對不同的子網絡使用不同的設置，以及提供權威域名服務器。</p><h3 id="更多參考" tabindex="-1">更多參考 <a class="header-anchor" href="#更多參考" aria-label="Permalink to “更多參考”">​</a></h3>`,44)),t("ul",null,[t("li",null,[n(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/7/dns-spoofing-dnsmasq"},{default:i(()=>[...s[0]||(s[0]=[a("使用 Dnsmasq 進行 DNS 偽裝",-1)])]),_:1})]),t("li",null,[n(e,{href:"https://www.linux.com/learn/dnsmasq-easy-lan-name-services"},{default:i(()=>[...s[1]||(s[1]=[a("使用 Dnsmasq 配置簡單的局域網域名服務",-1)])]),_:1})]),t("li",null,[n(e,{href:"http://www.thekelleys.org.uk/dnsmasq/doc.html"},{default:i(()=>[...s[2]||(s[2]=[a("Dnsmasq",-1)])]),_:1})])]),s[17]||(s[17]=t("hr",null,null,-1)),t("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/2/advanced-dnsmasq-tips-and-tricks"},{default:i(()=>[...s[3]||(s[3]=[a("https://www.linux.com/learn/intro-to-linux/2018/2/advanced-dnsmasq-tips-and-tricks",-1)])]),_:1})]),t("p",null,[s[8]||(s[8]=a("作者：",-1)),n(e,{href:"https://www.linux.com/users/cschroder"},{default:i(()=>[...s[5]||(s[5]=[a("CARLA SCHRODER",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),n(e,{href:"https://github.com/yixunx"},{default:i(()=>[...s[6]||(s[6]=[a("yixunx",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const D=l(r,[["render",h]]);export{x as __pageData,D as default};
